function extract(response) {
  if (!response || !Number.isFinite(response.status) || !Number.isInteger(response.status) || response.status < 100 || response.status > 599) return { ok: false, reason: "invalid_status" };
  if (response.status < 200 || response.status > 299) return { ok: false, reason: "http_error", status: response.status };
  const body = response.body;
  if (!body || !Array.isArray(body.content)) return { ok: false, reason: "invalid_content" };
  if (body.content.some((item) => item && typeof item === "object" && item.type === "refusal")) return { ok: false, reason: "refused" };
  if (body.stop_reason === "max_tokens") return { ok: false, reason: "incomplete" };
  if (body.stop_reason === "tool_use") return { ok: false, reason: "pending_tool" };
  if (body.stop_reason !== "end_turn") return { ok: false, reason: "invalid_stop_reason" };
  const text = body.content
    .filter((item) => item && typeof item === "object" && item.type === "text" && typeof item.text === "string")
    .map((item) => item.text)
    .join("");
  return text.length > 0 ? { ok: true, text, stopReason: body.stop_reason } : { ok: false, reason: "no_text_block" };
}

export function extractMessageReference(response) {
  return extract(response);
}
