import assert from "node:assert/strict";
import { fixtures as f } from "./fixtures.mjs";
import { extractMessage } from "./learner.mjs";

const groups = [
  ["aggregate_text", (check) => {
    check(() => extractMessage(f.mixed), { ok: true, text: "firstsecond", stopReason: "end_turn" });
    check(() => extractMessage(f.textOnly), { ok: true, text: "answer", stopReason: "end_turn" });
  }],
  ["missing_text", (check) => {
    check(() => extractMessage(f.empty), { ok: false, reason: "no_text_block" });
    check(() => extractMessage(f.nontext), { ok: false, reason: "no_text_block" });
    check(() => extractMessage(f.emptyText), { ok: false, reason: "no_text_block" });
  }],
  ["invalid_content", (check) => {
    check(() => extractMessage(f.nullContent), { ok: false, reason: "invalid_content" });
    check(() => extractMessage(f.objectContent), { ok: false, reason: "invalid_content" });
    check(() => extractMessage(f.missingContent), { ok: false, reason: "invalid_content" });
  }],
  ["malformed_items", (check) => {
    check(() => extractMessage(f.malformedItems), { ok: false, reason: "no_text_block" });
    check(() => extractMessage(f.malformedThenText), { ok: true, text: "kept", stopReason: "end_turn" });
  }],
  ["incomplete_or_pending", (check) => {
    check(() => extractMessage(f.incomplete), { ok: false, reason: "incomplete" });
    check(() => extractMessage(f.pendingTool), { ok: false, reason: "pending_tool" });
  }],
  ["typed_refusal", (check) => {
    check(() => extractMessage(f.refusedMixed), { ok: false, reason: "refused" });
    check(() => extractMessage(f.refusedOnly), { ok: false, reason: "refused" });
  }],
  ["http_status", (check) => {
    check(() => extractMessage(f.error401), { ok: false, reason: "http_error", status: 401 });
    check(() => extractMessage(f.statusString), { ok: false, reason: "invalid_status" });
    check(() => extractMessage(f.statusLow), { ok: false, reason: "invalid_status" });
    check(() => extractMessage(f.statusHigh), { ok: false, reason: "invalid_status" });
    check(() => extractMessage(f.statusFraction), { ok: false, reason: "invalid_status" });
  }],
  ["stop_policy", (check) => {
    check(() => extractMessage(f.unknownStop), { ok: false, reason: "invalid_stop_reason" });
    check(() => extractMessage(f.nullStop), { ok: false, reason: "invalid_stop_reason" });
  }]
];

let passed = 0;
let failed = 0;
let checks = 0;
let failedChecks = 0;
const failedGroups = [];
for (const [name, run] of groups) {
  let groupFailures = 0;
  const check = (operation, expected) => {
    checks += 1;
    try {
      assert.deepEqual(operation(), expected);
    } catch {
      groupFailures += 1;
      failedChecks += 1;
    }
  };
  run(check);
  if (groupFailures === 0) passed += 1;
  else {
    failed += 1;
    failedGroups.push(name);
  }
}
console.log(JSON.stringify({ passed, failed, checks, failedChecks, groups: failedGroups }));
if (failed > 0) process.exitCode = 1;
