import { extractMessage } from "./learner.mjs";

const apiKey = process.env.ANTHROPIC_API_KEY;
const model = process.env.PROJECT42_ANTHROPIC_MODEL;
if (!apiKey || !model) {
  console.log(JSON.stringify({ ok: false, reason: "missing_environment" }));
  process.exit(1);
}

try {
  const response = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "x-api-key": apiKey,
      "anthropic-version": "2023-06-01"
    },
    body: JSON.stringify({
      model,
      max_tokens: 300,
      messages: [{ role: "user", content: [{ type: "text", text: "Why use a bounded timeout?" }] }]
    }),
    signal: AbortSignal.timeout(30_000)
  });

  const requestId = response.headers.get("request-id") ?? "unknown";
  let body = null;
  try { body = await response.json(); } catch {}
  const result = extractMessage({ status: response.status, body });
  if (!result.ok) {
    console.log(JSON.stringify({ ok: false, status: response.status, requestId, reason: result.reason }));
    process.exitCode = 1;
  } else {
    const textBlocks = body.content.filter((item) => item && item.type === "text" && typeof item.text === "string").length;
    console.log(JSON.stringify({ ok: true, status: response.status, requestId, stopReason: result.stopReason, textBlocks }));
  }
} catch (error) {
  const reason = error && error.name === "TimeoutError" ? "timeout" : "request_failed";
  console.log(JSON.stringify({ ok: false, reason }));
  process.exitCode = 1;
}
